        function syncTopbarTransparency() {
          if (!topbar) return;
          topbar.classList.toggle("is-scrolled", window.scrollY > 10);
        }
        window.addEventListener("scroll", syncTopbarTransparency, { passive: true });
        syncTopbarTransparency();
        let toastTimer = null;
        function showToast(message) {
          if (!toast) {
            if (status) status.textContent = message || "";
            return;
          }
          toast.textContent = message || "";
          toast.classList.add("is-visible");
          clearTimeout(toastTimer);
          toastTimer = window.setTimeout(() => toast.classList.remove("is-visible"), Math.min(7200, Math.max(2200, String(message || "").length * 42)));
        }
        function businessMediaUploadElements(target) {
          if (target === "cover") return { state: coverUploadState, text: coverUploadText, percent: coverUploadPercent, bar: coverUploadBar };
          if (target === "library") return { state: libraryUploadState, text: libraryUploadText, percent: libraryUploadPercent, bar: libraryUploadBar };
          if (target === "profile") return { state: profileUploadState, text: profileUploadText, percent: profileUploadPercent, bar: profileUploadBar };
          return {};
        }
        function setBusinessMediaUploadProgress(target, progress, message, options = {}) {
          const elements = businessMediaUploadElements(target);
          if (!elements.state) return;
          const value = Math.max(1, Math.min(100, Math.round(Number(progress) || 1)));
          elements.state.hidden = false;
          elements.state.classList.toggle("is-failed", !!options.failed);
          elements.state.style.setProperty("--upload-progress", value + "%");
          if (elements.text) elements.text.textContent = message || (value >= 100 ? "Media ready." : "Uploading media...");
          if (elements.percent) elements.percent.textContent = options.failed ? "Needs attention" : value + "% done";
          if (elements.bar) elements.bar.style.width = value + "%";
        }
        function hideBusinessMediaUploadProgress(target, delay) {
          const elements = businessMediaUploadElements(target);
          if (!elements.state) return;
          const close = () => {
            elements.state.hidden = true;
            elements.state.classList.remove("is-failed");
          };
          if (delay) window.setTimeout(close, delay);
          else close();
        }
        function businessMediaUploadTargetLabel(target, type, name) {
          if (target === "profile") return "Profile photo";
          if (target === "cover") return type === "video" ? "Banner video" : "Banner image";
          if (target === "library") return type === "video" ? "Gallery video" : "Gallery image";
          return name || (type === "video" ? "Video" : "Image");
        }
