          if (!menu) return false;
          const isBusinessPostedMenu = menu.dataset.businessPostedMenu === "true" || !!(businessPostedFlow && businessPostedFlow.contains(menu));
          if (!isBusinessPostedMenu) return false;
          event.__emyBusinessPostedOptionHandled = true;
