          if (typeof event.stopImmediatePropagation === "function") event.stopImmediatePropagation();
          const card = option.closest("[data-feed-id]") || menu.__businessPostedCard || businessPostedCardForMenu(menu);
          const action = option.dataset.feedOption || option.dataset.businessPostOption || "";
          businessHandlePostedOption(action, card, menu, event);
          return true;
